    graph_base: s.graph_api_base,
    graph_version: s.graph_api_version,
  }));
}

function patientOutbox(ctx, patientId, waId, messages, purpose) {
  const s = ctx.settings || {};
  return (messages || []).map((m) => ({
    to: waId, phone_number_id: ctx.clinic.whatsapp_phone_number_id, clinic_id: ctx.clinic.id, patient_id: patientId,
    purpose: purpose || 'reply', message: m, graph_base: s.graph_api_base, graph_version: s.graph_api_version,
  }));
}


// ===== lógica do nó =====
const j = $json; const ev = j.ev || {}; const ctx = j.ctx;
const cmd = (ev.type === 'text') ? parseStaffCommand(ev.text) : { cmd: 'help' };
const map = { list: 'list', assign: 'assign', release: 'release', reply: 'reply', takeover: 'takeover' };
return { json: Object.assign({}, j, { cmd, valid: !!map[cmd.cmd],
  args: { clinic_id: ctx.clinic.id, staff_id: ctx.staff.id, action: map[cmd.cmd] || 'list', code: cmd.code || null, patient_wa_id: cmd.patient_wa_id || null } }) };

